export default function Icon({ name, size, label, className }) {
  const icon = ICONS[name];
  const [w, h] = Array.isArray(icon.box) ? icon.box : [icon.box, icon.box];
  const width = size ?? w;
  return (
    <svg
      className={className}
      width={width}
      height={(width * h) / w}
      viewBox={`0 0 ${w} ${h}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {icon.body}
    </svg>
  );
}
